#ifndef REMIX_LEVEL_H
#define REMIX_LEVEL_H

#include "ultra64.h"

struct GameState;
struct PlayState;

// Web Remix new levels (src/code/z_remix_level.c). The levels themselves are generated by
// tools/remix/make_level.py into assets/scenes/remix/.

// Scene draw config of the Ancient Plateau (SDC_REMIX_ANCIENT): glow pulses, flowing circuit light and water, the
// Spire's moving parts and the rocks circling the floating island, fed to the room's display lists through
// segments 0x08-0x0F.
void RemixLevel_DrawConfigAncient(struct PlayState* play);

// Scene draw config of the Ember Shrine (SDC_REMIX_SHRINE, level 2, tools/remix/make_shrine.py): glow, the circuit
// lines of each stage of its trial lit by the stage's switch flag, the rune ring over the altar.
void RemixLevel_DrawConfigShrine(struct PlayState* play);

// Scene draw config of the Seeker's Shrine (SDC_REMIX_SEEKER, level 3, tools/remix/make_seeker.py): what the Lens of
// Truth shows and takes away, each tool's circuit lines once found, the rune ring over the altar.
void RemixLevel_DrawConfigSeeker(struct PlayState* play);

// Scene draw config of the Lodestone Shrine (SDC_REMIX_MAGNET, level 4, tools/remix/make_magnet.py): Magnesis's
// circuit lines once the rune is found, the lift's while it runs, the rune ring over the altar.
void RemixLevel_DrawConfigMagnet(struct PlayState* play);

// Scene draw config of the Forge Shrine (SDC_REMIX_FORGE, level 5, tools/remix/make_forge.py): each stage's circuit
// lines once its torch is lit, the rune ring over the exit.
void RemixLevel_DrawConfigForge(struct PlayState* play);

// Called by Play_Init once the scene is chosen (src/code/z_play.c): the Seeker's Shrine takes Link's items on the
// way in (all but swords, shields and tunics; a full magic meter for the Lens found inside) and gives them back as
// soon as he is anywhere else.
void RemixLevel_OnSceneStart(struct PlayState* play);
// Sram_WriteSave writes Link's own items, not the trial's (called before and after writing).
void RemixLevel_TrialSaveSwap(void);
// A save was loaded or made: there is no trial in progress.
void RemixLevel_TrialForget(void);

// Object space of the Ancient Plateau (src/code/z_scene.c): its room's objects take about 893 KB with the keep
// objects and adult Link, so it reserves less than the usual 1000 KB and the rest goes to actor memory (the
// town's people). The remix build checks that the objects fit (.github/workflows/remix.yml).
#define REMIX_ANCIENT_OBJECT_SPACE (900 * 1024)

// Sends Link to the Ancient Plateau from anywhere in the game.
void RemixLevel_GoToAncient(struct PlayState* play);
// Sends Link down into the Ember Shrine (its exit then takes him up the hole in the Ancient Plateau).
void RemixLevel_GoToShrine(struct PlayState* play);
// And into the Seeker's Shrine.
void RemixLevel_GoToSeeker(struct PlayState* play);
// And into the Lodestone Shrine.
void RemixLevel_GoToMagnet(struct PlayState* play);
// And into the Forge Shrine.
void RemixLevel_GoToForge(struct PlayState* play);

// "Boot straight into the new level": the website sets `mode` in the ROM it hands to the emulator (it finds
// the struct by its magic). The console logo screen then starts a test save in the Ancient Plateau instead of
// going to the title screen.
typedef struct RemixBootConfig {
    /* 0x00 */ char magic[8]; // "RMXBOOT1"
    /* 0x08 */ u8 mode;       // REMIX_BOOT_*
    /* 0x09 */ u8 pad[7];
} RemixBootConfig;

#define REMIX_BOOT_NORMAL 0       // title screen as usual
#define REMIX_BOOT_ANCIENT 1      // the Ancient Plateau, as adult Link
#define REMIX_BOOT_HYRULE_FIELD 2 // Hyrule Field the same way (tests: tools/remix/smoke_test.py)
#define REMIX_BOOT_ISLAND_VIEW 3  // the Ancient Plateau, standing on the floating island (tests)
#define REMIX_BOOT_POOL_VIEW 4    // the Ancient Plateau, at the pool facing the waterfall (tests)
#define REMIX_BOOT_SHRINE 5       // level 2: the Ember Shrine, as adult Link, dropping in from its hole
#define REMIX_BOOT_SEEKER 6       // level 3: the Seeker's Shrine, the same way (with nothing but the sword)
#define REMIX_BOOT_MAGNET 7       // level 4: the Lodestone Shrine, the same way
#define REMIX_BOOT_MAGNET_TEST 8  // the Lodestone Shrine with Magnesis, facing the iron slab (tests)
#define REMIX_BOOT_MAGNET_CHEST 9 // the Lodestone Shrine, in front of the rune's chest (tests)
#define REMIX_BOOT_FORGE 10       // level 5: the Forge Shrine, the same way as the others
#define REMIX_BOOT_FORGE_TEST 11  // the Forge Shrine, behind the burning basket, facing the first gate (tests)

extern RemixBootConfig gRemixBootConfig;

s32 RemixBoot_IsRequested(void);
void RemixBoot_Start(struct GameState* gameState);

#endif
